  const s1 = N + eu[j];
  const s2 = N + ev[j];
  addEdge(s1, s2, 0);
  addEdge(s2, s1, 0);
}

const dist = new Float64Array(Vtotal);
dist.fill(Infinity);

const start = A - 1;
const target = B - 1;
dist[start] = 0;

const heapNode = [];
const heapDist = [];
let popDist = 0;

function heapPush(node, d) {
  let i = heapNode.length;
  heapNode.push(node);
  heapDist.push(d);

  while (i > 0) {
    const p = (i - 1) >> 1;
    if (heapDist[p] <= d) break;
    heapNode[i] = heapNode[p];
    heapDist[i] = heapDist[p];
    i = p;
  }

  heapNode[i] = node;
  heapDist[i] = d;
}

function heapPop() {
  const resNode = heapNode[0];
  popDist = heapDist[0];

  const lastNode = heapNode.pop();
  const lastDist = heapDist.pop();

  if (heapNode.length > 0) {
    heapNode[0] = lastNode;
    heapDist[0] = lastDist;

    let i = 0;
    const n = heapNode.length;

    while (true) {
      const l = i * 2 + 1;
      const r = l + 1;
      let smallest = i;

      if (l < n && heapDist[l] < heapDist[smallest]) smallest = l;
      if (r < n && heapDist[r] < heapDist[smallest]) smallest = r;
      if (smallest === i) break;

      const tmpNode = heapNode[i];
      heapNode[i] = heapNode[smallest];
      heapNode[smallest] = tmpNode;

      const tmpDist = heapDist[i];
      heapDist[i] = heapDist[smallest];
      heapDist[smallest] = tmpDist;

      i = smallest;
    }
  }

  return resNode;
}

heapPush(start, 0);

while (heapNode.length > 0) {
  const u = heapPop();
  const d = popDist;

  if (d !== dist[u]) continue;
  if (u === target) break;

  for (let e = head[u]; e !== -1; e = next[e]) {
    const v = to[e];
    const nd = d + weight[e];

    if (nd < dist[v]) {
      dist[v] = nd;
      heapPush(v, nd);
    }
  }
}

const ans = dist[target];
if (ans === Infinity) {
  console.log(-1);
} else {
  console.log(ans);
}
